import { DatabaseSync } from 'node:sqlite';
function main(): void {
  const db = new DatabaseSync(':memory:');
  const row: any = db.prepare('SELECT ? AS n, ? AS r, ? AS t, ? AS i, ? AS inf').get(null, 1.5, 'hello', 7, Infinity);
  console.log(row.n, row.r, row.t, row.i, row.inf);
  console.log(JSON.stringify(db.prepare('SELECT typeof(?) AS a, typeof(?) AS b').get(2, 'x')));
  db.close();
}
